//! Cargo-driven `dwrite.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("dwrite-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:uuid", "engine:oldnames", "engine:c:freetype", "import:shell32", "import:shlwapi", "import:oleaut32", "import:ole32", "import:user32", "import:user32_vista", "import:gdi32", "import:msvcrt", "import:advapi32", "import:advapi32_vista", "import:kernel32", "import:kernel32_vista", "import:ntdll", "body"],
        "x86_64" => &["engine:wine", "engine:uuid", "engine:oldnames", "engine:c:freetype", "import:shell32", "import:shlwapi", "import:oleaut32", "import:ole32", "import:user32", "import:user32_vista", "import:gdi32", "import:msvcrt", "import:advapi32", "import:advapi32_vista", "import:kernel32", "import:kernel32_vista", "import:ntdll", "body"],
        "aarch64" => &["engine:wine", "engine:uuid", "engine:oldnames", "engine:c:freetype", "import:shell32", "import:shlwapi", "import:oleaut32", "import:ole32", "import:user32", "import:user32_vista", "import:gdi32", "import:msvcrt", "import:advapi32", "import:advapi32_vista", "import:kernel32", "import:kernel32_vista", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("dwrite_shims", &["dll/directx/wine/dwrite/shapers/arabic_table.c", "dll/directx/wine/dwrite/shapers/arabic.c", "dll/directx/wine/dwrite/analyzer.c", "dll/directx/wine/dwrite/bidi.c", "dll/directx/wine/dwrite/bracket.c", "dll/directx/wine/dwrite/direction.c", "dll/directx/wine/dwrite/font.c", "dll/directx/wine/dwrite/format.c", "dll/directx/wine/dwrite/freetype.c", "dll/directx/wine/dwrite/gdiinterop.c", "dll/directx/wine/dwrite/layout.c", "dll/directx/wine/dwrite/linebreak.c", "dll/directx/wine/dwrite/main.c", "dll/directx/wine/dwrite/mirror.c", "dll/directx/wine/dwrite/opentype.c", "dll/directx/wine/dwrite/reactos.c", "dll/directx/wine/dwrite/scripts.c", "dll/directx/wine/dwrite/shape.c"])
        .spec2def("dll/directx/wine/dwrite/dwrite.spec", "dwrite.dll")
        .spec_stubs()
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/user/user32_vista/user32_vista.spec", "user32_vista.dll", "user32_vista")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
